1	package netdiag
2	
3	import (
4		"fmt"
5		"net/netip"
6		"strings"
7	
8		"github.com/anthnel/devdesk/internal/docker"
9	)
10	
11	// containerAttach says how a container is attached to a network.
12	type containerAttach int
13	
14	// The ways a container can be attached.
15	const (
16		attachNetwork containerAttach = iota
17		attachHost
18		attachNone
19		attachShared
20		attachUndetermined
21	)
22	
23	// pathContainer is what the column says about the container a trace starts in.
24	type pathContainer struct {
25		Name     string // display-safe
26		Known    bool   // false: the inspection failed
27		Running  bool
28		Attach   containerAttach
29		Network  string     // attachNetwork only, display-safe
30		Networks int        // number of endpoints, for "undetermined (N networks)"
31		Addr     netip.Addr // the container's IPv4 on Network
32		Gateway  netip.Addr // Network's gateway
33	}
34	
35	const (
36		modeHost            = "host"
37		modeNone            = "none"
38		modeSharedPrefix    = "container:"
39		textUndetermined    = "undetermined"
40		textHostNetwork     = "host (shares this machine's stack)"
41		textNoNetwork       = "none (no network)"
42		textSharedNetwork   = "shares another container's network"
43		textNotRunning      = "not running"
44		textTraceFromHost   = "from this machine, not from the container"
45		textTraceSharedHost = "from this machine (shared with the container)"
46	)
47	
48	// newPathContainer converts an inspection into a pathContainer. Every text the
49	// engine returned is sanitized here, so the cells are display-safe.
50	func newPathContainer(src pathSource, n docker.ContainerNetworking, err error) pathContainer {
51		c := pathContainer{Name: src.Name, Attach: attachUndetermined}
52		if err != nil {
53			return c
54		}
55		c.Known = true
56		if name := engineText(n.Name); name != "" {
57			c.Name = name
58		}
59		c.Running = n.Running
60		if !n.Running {
61			return c
62		}
63		switch {
64		case n.Mode == modeHost:
65			c.Attach = attachHost
66		case n.Mode == modeNone:
67			c.Attach = attachNone
68		case strings.HasPrefix(n.Mode, modeSharedPrefix):
69			c.Attach = attachShared
70		default:
71			c.Networks = len(n.Networks)
72			if picked, ok := defaultRouteNetwork(n.Networks); ok {
73				c.Attach = attachNetwork
74				c.Network = engineText(picked.Name)
75				c.Addr = picked.IPv4
76				c.Gateway = picked.Gateway
77			}
78		}
79		return c
80	}
81	
82	// defaultRouteNetwork picks the network that holds the container's default
83	// route: among the endpoints with a gateway, the one with the strictly highest
84	// gateway priority. A tie, or a priority missing among several candidates, is
85	// never guessed. The input is not modified.
86	func defaultRouteNetwork(nets []docker.EndpointNetwork) (docker.EndpointNetwork, bool) {
87		var candidates []docker.EndpointNetwork
88		for _, e := range nets {
89			if e.Gateway.IsValid() {
90				candidates = append(candidates, e)
91			}
92		}
93		switch len(candidates) {
94		case 0:
95			return docker.EndpointNetwork{}, false
96		case 1:
97			return candidates[0], true
98		}
99		best := -1
100		for i, e := range candidates {
101			if e.GwPriority == nil {
102				return docker.EndpointNetwork{}, false
103			}
104			if best < 0 || *e.GwPriority > *candidates[best].GwPriority {
105				best = i
106			}
107		}
108		for i, e := range candidates {
109			if i != best && *e.GwPriority == *candidates[best].GwPriority {
110				return docker.EndpointNetwork{}, false
111			}
112		}
113		return candidates[best], true
114	}
115	
116	// containerText is the Address cell of the container row.
117	func (c pathContainer) containerText() string {
118		switch {
119		case c.Known && !c.Running:
120			return c.Name + " (" + textNotRunning + ")"
121		case c.Attach == attachNetwork && c.Addr.IsValid():
122			return c.Name + " (" + c.Addr.String() + ")"
123		}
124		return c.Name
125	}
126	
127	// networkText is the Address cell of the network row.
128	func (c pathContainer) networkText() string {
129		switch c.Attach {
130		case attachNetwork:
131			if c.Gateway.IsValid() {
132				return c.Network + " via " + c.Gateway.String()
133			}
134			return c.Network
135		case attachHost:
136			return textHostNetwork
137		case attachNone:
138			return textNoNetwork
139		case attachShared:
140			return textSharedNetwork
141		}
142		if c.Networks > 1 {
143			return fmt.Sprintf("%s (%d networks)", textUndetermined, c.Networks)
144		}
145		return textUndetermined
146	}
147	
148	// traceText is the Address cell of the trace row.
149	func (c pathContainer) traceText() string {
150		if c.Attach == attachHost {
151			return textTraceSharedHost
152		}
153		return textTraceFromHost
154	}
155	
156	// dimNetwork reports whether the network row says nothing about a path.
157	func (c pathContainer) dimNetwork() bool {
158		return c.Attach == attachUndetermined || c.Attach == attachNone
159	}
