15	// pathBarLabel prefixes the target field in the bar.
16	const pathBarLabel = "Target › "
17	
18	// pathColumns describes the Path column. Plain text in Cell, colour in Style
19	// (Rule 122). A silent hop is dim, never red: it is not a failure.
20	func pathColumns() []datatable.Column[pathStep] {
21		hop := datatable.Column[pathStep]{
22			Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
23			Cell: pathStep.hopCell,
24		}
25		step := datatable.Column[pathStep]{
26			Title: "Step", Sizing: datatable.SizingFixed, MinWidth: 11,
27			Cell:  pathStep.stepCell,
28			Style: pathStepStyle,
29		}
30		address := datatable.Column[pathStep]{
31			Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
32			Cell:  pathStep.addressCell,
33			Style: pathAddressStyle,
34		}
35		rtt := datatable.Column[pathStep]{
36			Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
37			Cell:  pathStep.rttCell,
38			Style: pathRTTStyle,
39		}
40		return []datatable.Column[pathStep]{hop, step, address, rtt}
41	}
42	
43	func pathStepStyle(s pathStep) lipgloss.Style {
44		if s.Kind != stepHop {
45			return lipgloss.Style{}
46		}
47		switch s.Hop.Kind {
48		case nettrace.HopSilent, nettrace.HopUnresolved:
49			return theme.DimStyle
50		case nettrace.HopError:
51			return theme.SeverityTextStyle("MEDIUM")
52		}
53		return lipgloss.Style{}
54	}
55	
56	func pathAddressStyle(s pathStep) lipgloss.Style {
57		switch s.Kind {
58		case stepTrace:
59			return theme.DimStyle
60		case stepNetwork:
61			if s.Container.dimNetwork() {
62				return theme.DimStyle
63			}
64		case stepHop:
65			if !s.Hop.Addr.IsValid() {
66				return theme.DimStyle
67			}
68		case stepInterface, stepGateway:
69			if c := s.addressCell(); c == routeUndetermined || c == gatewayDirect {
70				return theme.DimStyle
71			}
72		}
73		return lipgloss.Style{}
74	}
75	
76	func pathRTTStyle(s pathStep) lipgloss.Style {
77		if s.Kind == stepHop && s.Hop.RTT <= 0 {
78			return theme.DimStyle
79		}
80		return lipgloss.Style{}
81	}
82	
83	// view renders the table; the body is never replaced (Rule 139). The open
84	// selector is drawn over it.
85	func (pm *PathModel) view() string {
86		if pm.pickerOpen() {
87			return pm.viewWithPicker(pm.table.View())
88		}
89		return pm.table.View()
90	}
91	
92	// barView is the target field in its frame, two lines in every state.
93	func (pm *PathModel) barView(width int) string {
94		return components.BarFrame(width, theme.KeyStyle.Render(pathBarLabel)+pm.input.View())
95	}
96	
97	// statusLine is derived on every frame (Rule 128).
98	func (pm *PathModel) statusLine() components.Status {
99		if pm.errText != "" {
100			return components.Status{Text: pm.errText, Level: components.LevelError}
101		}
102		if pm.pickerOpen() {
103			return pm.pickerStatus()
104		}
105		if pm.state != pathRunning {
106			return components.Status{}
107		}
108		host := pm.target.Host
109		n := pm.hopCount()
110		if !pm.addr.IsValid() && n == 0 {
111			return components.Status{Text: "Resolving " + host + "...", Activity: true}
112		}
113		where := host
114		if pm.addr.IsValid() && pm.addr.String() != host {
115			where += " (" + pm.addr.String() + ")"
116		}
117		noun := "hops"
118		if n == 1 {
119			noun = "hop"
120		}
121		return components.Status{
122			Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
123			Activity: true,
124		}
125	}
126	
127	// headerInfo lists the target and, once a run ended, how it ended.
128	func (pm *PathModel) headerInfo() []shortcut.HeaderInfo {
129		var out []shortcut.HeaderInfo
130		if !pm.source.isHost() {
131			out = append(out, shortcut.HeaderInfo{Key: "Source", Value: pm.source.Name, Style: theme.HeaderValueStyle})
132		}
133		if pm.target.Host != "" {
134			value := pm.target.String()
135			if pm.addr.IsValid() && pm.addr.String() != pm.target.Host {
136				value += " (" + pm.addr.String() + ")"
137			}
138			out = append(out, shortcut.HeaderInfo{Key: "Target", Value: value, Style: theme.HeaderValueStyle})
139		}
140		if pm.result != nil {
141			out = append(out, shortcut.HeaderInfo{Key: "Path", Value: pathOutcomeLabel(*pm.result), Style: theme.HeaderValueStyle})
142		}
143		return out
144	}
145	
146	// shortcuts: the running mode replaces the list, the other states grey out
147	// (Rule 130).
148	func (pm *PathModel) shortcuts() shortcut.Shortcuts {
149		if pm.pickerOpen() { // a mode: the list is replaced
150			return shortcut.Shortcuts{
151				{Key: "enter", Description: "Trace from it"},
152				{Key: "esc", Description: "Close"},
153			}
154		}
155		off := !pm.launchable().Enabled()
156		source := shortcut.Shortcut{Key: pathSourceKey, Description: "Trace from…", Disabled: !pm.sourceChoosable().Enabled()}
157		switch pm.state {
158		case pathRunning:
159			return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
160		case pathDone:
161			return shortcut.Shortcuts{
162				{Key: "tab", Description: "Switch tab"},
163				{Key: "enter", Description: "Trace again", Disabled: off},
164				source,
165				{Key: "esc", Description: "Edit the target"},
166				{Key: "?", Description: "Help"},
167			}
168		}
169		return shortcut.Shortcuts{
170			{Key: "tab", Description: "Switch tab"},
171			{Key: "enter", Description: "Trace the path", Disabled: off},
172			source,
173		}
174	}
